WITH filtered AS (SELECT id, promo_code, discount_pct, CASE WHEN discount_pct >= 0.3 THEN 'High' WHEN discount_pct >= 0.13 THEN 'Medium' ELSE 'Low' END AS discount_pct_level FROM promotions WHERE starts_on >= DATE '2023-09-05' AND channel IS NOT NULL), enriched AS (SELECT *, LEAD(discount_pct) OVER w_grp AS next_discount_pct, ROW_NUMBER() OVER w_grp AS event_seq, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct FROM filtered WINDOW w_grp AS (PARTITION BY promo_code ORDER BY discount_pct ASC, id ASC)), valid AS (SELECT *, CAST(next_discount_pct AS INT) AS next_discount_pct_int FROM enriched WHERE running_discount_pct BETWEEN 1 AND 2), deduped AS (SELECT * FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY next_discount_pct DESC, id ASC) = 1), scored AS (SELECT *, FIRST_VALUE(event_seq, TRUE) OVER (PARTITION BY promo_code ORDER BY next_discount_pct_int ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_event_seq, AVG(running_discount_pct) OVER (ORDER BY running_discount_pct ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS running_discount_pct_avg_3_prior, NTILE(3) OVER (ORDER BY next_discount_pct DESC, id ASC) AS next_discount_pct_bucket FROM deduped), base AS (SELECT *, ROUND(running_discount_pct_avg_3_prior, 0) AS running_discount_pct_avg_3_prior_rounded, CEIL(event_seq) AS event_seq_whole FROM scored WHERE running_discount_pct < 1) SELECT CASE WHEN first_known_event_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END AS first_known_event_seq_tier, PERCENTILE_APPROX(running_discount_pct_avg_3_prior_rounded, 0.95) AS running_discount_pct_avg_3_prior_rounded_p95, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, COUNT(*) AS event_count FROM base GROUP BY CASE WHEN first_known_event_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END HAVING event_count < 1000 ORDER BY running_discount_pct_avg_3_prior_rounded_p95 DESC
